/**
 * Function       brake
 * @author        Danny
 * @date          2017.08.16
 * @brief         小车刹车
 * @param[in]     time
 * @param[out]    void
 * @retval        void
 * @par History   无
 */
void brake(unsigned int time)
{
    //左电机停止
    Left_motor_go = 0;    //左电机前进禁止
    Left_motor_back = 0;  //左电机后退禁止

    //右电机停止
    Right_motor_go=0;     //右电机前进禁止
    Right_motor_back=0;   //右电机后退禁止

    //延时
    delay(time * 100);
    return;
}
