/**
 * Function       rimer0
 * @author        Danny
 * @date          2017.08.16
 * @brief         TIMER0中断服务子函数产生PWM信号,
 * @param[in]     void
 * @param[out]    void
 * @retval        void
 * @par History   无
 */
void timer0() interrupt 1 using 2
{
    TH0=0XFC;          //1Ms定时
    TL0=0X66;
    pwm_val_left++;
    pwm_val_right++;
    pwm_out_left_motor();
    pwm_out_right_motor();
}
